Import ListNotations.
Open Scope bv_scope.
Import ITree.Exc.

(* [comment removed for export] *)
(* [comment removed for export] *)
(* [comment removed for export] *)
Definition PATEXIT : Z := 0x1d798.        (* [comment removed for export] *)
Definition PATX : Z := 0x57878.           (* [comment removed for export] *)
Definition PATX_CALLFN : Z := 0x1d85c.    (* [comment removed for export] *)
Definition PNEED_LOCKS : Z := 0x57ac3.    (* [comment removed for export] *)
Definition PATEXIT_STACK : Z := 48.
(* [comment removed for export] *)
Definition PEXIT_GUARD : Z := 0x13158.    (* [comment removed for export] *)
Definition PAEF_INCB : Z := 0x37734.      (* [comment removed for export] *)

(* [comment removed for export] *)
Definition atx_cells (head slot f0 a0 : Z) (m : word -> option byte) : Prop :=
  rw_cells psegs m 0x57878 [C1 (Z_to_bv 8 0)]
  /\ rw_cells psegs m (0x5787c) [C4 (Z_to_bv 64 0)]
  /\ rw_cells psegs m (0x57880) [C4 (Z_to_bv 64 slot)]
  /\ rw_cells psegs m (0x57888) [C8 (Z_to_bv 64 head)]
  /\ rw_cells psegs m (0x57890) [C8 (Z_to_bv 64 0)]
  /\ rw_cells psegs m (0x57898) [C8 (Z_to_bv 64 f0)]
  /\ rw_cells psegs m (0x57998) [C8 (Z_to_bv 64 a0)].

(* [comment removed for export] *)
Definition atx_state (reg : bool) (m : word -> option byte) : Prop :=
  atx_cells (if reg then 0x57890 else 0) (if reg then 1 else 0) (if reg then PATX_CALLFN else 0) (if reg then PEXIT_GUARD else 0) m
  /\ rw_cells psegs m PAEF_INCB [C1 (Z_to_bv 8 0)].

(* [comment removed for export] *)
Definition atx_addr (a : Z) : Prop :=
  (0x57878 <= a < 0x57879)%Z \/ (0x5787c <= a < 0x57884)%Z \/ (0x57888 <= a < 0x578a0)%Z \/ (0x57998 <= a < 0x579a0)%Z.

Definition atx_state_addr (a : Z) : Prop := atx_addr a \/ (PAEF_INCB <= a < PAEF_INCB + 1)%Z.

Lemma atx_cells_agree : forall (P : Z -> Prop) m m' head slot f0 a0,
  magree psegs P m m' -> (forall a, atx_addr a -> P a) -> atx_cells head slot f0 a0 m -> atx_cells head slot f0 a0 m'.
Proof.
